import jwt
import hmac
import hashlib
import os
from flask import Flask, request, jsonify
from functools import wraps
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend

app = Flask(__name__)

# Configuration
RSA_PUBLIC_KEY = open('/etc/app/public.pem', 'rb').read()
RSA_PRIVATE_KEY = open('/etc/app/private.pem', 'rb').read()
HMAC_SECRET = os.environ.get('HMAC_SECRET', os.urandom(64).hex())

ALLOWED_ALGORITHMS = ['RS256', 'HS256']

def get_verification_key(token):
    """Determine the correct verification key based on the token's algorithm.

    For RS256 tokens (from external IdP): use RSA public key
    For HS256 tokens (internal service-to-service): use HMAC secret
    """
    try:
        unverified_header = jwt.get_unverified_header(token)
    except jwt.exceptions.DecodeError:
        raise ValueError("Invalid token format")

    alg = unverified_header.get('alg', '')

    if alg not in ALLOWED_ALGORITHMS:
        raise ValueError(f"Algorithm {alg} not allowed")

    if alg == 'RS256':
        return RSA_PUBLIC_KEY
    elif alg == 'HS256':
        return HMAC_SECRET
    else:
        raise ValueError("Unsupported algorithm")

def validate_token_claims(payload):
    """Validate required claims exist and are well-formed."""
    required = ['sub', 'exp', 'iss']
    for claim in required:
        if claim not in payload:
            raise ValueError(f"Missing required claim: {claim}")

    valid_issuers = ['https://idp.company.com', 'internal-service']
    if payload['iss'] not in valid_issuers:
        raise ValueError(f"Invalid issuer: {payload['iss']}")

    return True

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing bearer token'}), 401

        token = auth_header[7:]

        try:
            key = get_verification_key(token)

            payload = jwt.decode(
                token,
                key,
                algorithms=ALLOWED_ALGORITHMS,
                options={"require": ["exp", "sub", "iss"]}
            )

            validate_token_claims(payload)
            request.user = payload

        except (jwt.InvalidTokenError, ValueError) as e:
            return jsonify({'error': 'Authentication failed'}), 401

        return f(*args, **kwargs)
    return decorated

@app.route('/api/admin/users', methods=['GET'])
@require_auth
def list_users():
    if request.user.get('role') != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    return jsonify({'users': ['alice', 'bob', 'charlie']})

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    return jsonify({'user': request.user['sub'], 'issuer': request.user['iss']})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
